import Foundation

enum ReadingContentService {
    /// Each age group reads one story in episodes: today's text is the first episode the child hadn't finished
    /// before today, so it stays put all day and the story moves on tomorrow. Once every episode is done,
    /// the episodes repeat in a stable daily order.
    static func textForToday(profile: ChildProfile, date: String, history: [ReadingSession]) -> ReadingText {
        let texts = allTexts.filter { $0.ageGroup == profile.ageGroup }
        guard !texts.isEmpty else { return allTexts[0] }
#if DEBUG
        // Both localized demo takes use the same real passage and speech/highlighting path.
        let arguments = ProcessInfo.processInfo.arguments
        if arguments.contains("-demoRecording"), arguments.contains("-demoReading") {
            return texts[0]
        }
#endif
        let finished = Set(history.filter { $0.isCompleted && $0.date < date }.map(\.readingTextId))
        if let next = texts.first(where: { !finished.contains($0.id) }) {
            return next
        }
        // FNV-1a stays stable across launches, unlike Swift's randomized hashValue.
        let hash = (date + ":" + profile.id).utf8.reduce(UInt64(14695981039346656037)) {
            ($0 ^ UInt64($1)) &* 1099511628211
        }
        return texts[Int(hash % UInt64(texts.count))]
    }

    static func parseWords(from text: String) -> [ReadingWord] {
        let components = text.components(separatedBy: " ").filter { !$0.isEmpty }
        var words: [ReadingWord] = []
        var charIndex = 0
        for (i, word) in components.enumerated() {
            let start = charIndex
            let end = charIndex + word.count
            words.append(ReadingWord(id: i, text: word, startIndex: start, endIndex: end))
            charIndex = end + 1
        }
        return words
    }

    static func secondsPerWord(totalWords: Int, targetSeconds: Int) -> Double {
        guard totalWords > 0 else { return 1.0 }
        return Double(targetSeconds) / Double(totalWords)
    }

    /// Episodes in reading order. One cast across all ages: Mia, Grandpa, Rex the dog and Pancake the cat.
    static let allTexts: [ReadingText] = youngTexts + middleTexts + olderTexts

