    /// Ages 7–8: the week before the summer fair, everything Grandpa enters goes wonderfully wrong.
    private static let middleTexts: [ReadingText] = [
        ReadingText(
            id: "m1", titleEN: "Grandpa’s Pancake Machine", titleNO: "Bestefars pannekakemaskin",
